export function getBackgroundStartingEquipment(
  idOrSlug: string,
): BackgroundEquipmentPackage {
  const clean = idOrSlug.replace(/^.*:background:/, '').toLowerCase();
  return (
    BACKGROUND_STARTING_EQUIPMENT[clean] ?? {
      slug: clean,
      name: 'Custom',
      label: 'Set of Traveler’s Clothes, Belt Pouch, and 100 CR',
      items: [
        { name: 'Set of Traveler’s Clothes', kind: 'equipment', quantity: 1, weight: 4, cost: 20 },
        { name: 'Belt Pouch', kind: 'equipment', quantity: 1, weight: 1, cost: 5 },
      ],
      credits: 100,
    }
  );
}

